import networkx as nx
import graphcalc as gc

print('Testing small graphs...')
found = []
for n in range(2, 9):
    for G in nx.graph_atlas_g():
        if G.number_of_nodes() == n and nx.is_connected(G):
            rad = nx.radius(G)
            rom = gc.roman_domination_number(G)
            if rad + 1 > rom:
                found.append((n, list(G.edges()), rad, rom))
                print(f'Counterexample found! n={n}, rad={rad}, rom={rom}, edges={list(G.edges())}')
                break
    if found:
        break
if not found:
    print('No counterexamples up to order 7 in graph atlas!')
